const THEMES = Object.freeze({
  classic: { background: '#f3f4f6', surface: '#ffffff', ink: '#152033', muted: '#657189', accent: '#6257e8', accent2: '#15b8a6' },
  modern: { background: '#1a1a2e', surface: '#22223a', ink: '#f5f4ff', muted: '#a8aec5', accent: '#e94560', accent2: '#42d9c2' },
  minimal: { background: '#faf9f6', surface: '#ffffff', ink: '#20201f', muted: '#6c6a65', accent: '#30302d', accent2: '#b3a58c' },
});

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
}

export function sanitizeContent(text) {
  const stripped = String(text ?? '').replace(/<!--[\s\S]*?-->|<\/?[A-Za-z][^>]*>/g, '').trim();
  return escapeHtml(stripped).replace(/\r\n?|\n/g, '<br>');
}

function displayValue(value) {
  return value === null || value === undefined || value === '' ? 'غير محدد' : String(value);
}

function categoryFor(job) {
  const text = `${job.title || ''} ${job.description || ''}`.toLowerCase();
  if (/ترجم|translation|proofread|تحرير|كتابة|محتوى|article|copywrit|writer|editor/.test(text)) return 'editorial';
  if (/تصميم|هوية|شعار|logo|brand|graphic|illustrat|ui\/ux|visual/.test(text)) return 'creative';
  if (/تسويق|marketing|campaign|social media|سوشيال|seo|sales|مبيعات|إعلان|advert/.test(text)) return 'campaign';
  if (/فيديو|مونتاج|video|reel|motion|animation|يوتيوب|youtube/.test(text)) return 'video';
  return 'service';
}

function featureItems(job, proposal) {
  const tasks = Array.isArray(job.estimated_tasks) ? job.estimated_tasks
    .map((task) => typeof task === 'string' ? task : task?.name)
    .filter((task) => typeof task === 'string' && task.trim()) : [];
  const source = tasks.length ? tasks.join('\n') : `${job.description || ''}\n${proposal || ''}`;
  const entries = source.split(/[\n.!؟?؛;]+/).map((line) => line.replace(/^[-*•\d.)\s]+/, '').trim()).filter((line) => line.length >= 8);
  const unique = [...new Set(entries)];
  if (unique.length) return unique.slice(0, 3);
  return ['تحديد المطلوب والتفاصيل', 'إعداد نموذج أولي قابل للمراجعة', 'تطوير النتيجة حسب ملاحظاتك'];
}

function previewFor(category, job) {
  const title = sanitizeContent(job.title || 'فكرة المشروع');
  if (category === 'editorial') return `<div class="editor-preview">
    <div class="editor-toolbar"><span></span><span></span><span></span><b>مساحة المحتوى</b></div>
    <div class="editor-paper"><small>مسودة توضيحية</small><h3>${title}</h3><p class="line long"></p><p class="line"></p><p class="line medium"></p><blockquote>نص واضح، منسق، ومناسب للجمهور المستهدف.</blockquote><p class="line long"></p><p class="line short"></p></div>
    <div class="editor-side"><i></i><i></i><i></i><i></i></div>
  </div>`;
  if (category === 'creative') return `<div class="brand-preview">
    <div class="brand-top"><span class="brand-symbol">✳</span><span>لوحة الاتجاه البصري</span><span class="pill">تصور مبدئي</span></div>
    <div class="brand-canvas"><div class="brand-orb"></div><div class="brand-type"><small>اتجاه بصري مقترح</small><strong>${title}</strong><span>لون · خط · تكوين</span></div><div class="brand-stamp">Aa</div></div>
    <div class="swatches"><i></i><i></i><i></i><i></i><span>لوحة ألوان أولية</span></div>
  </div>`;
  if (category === 'campaign') return `<div class="campaign-preview">
    <div class="campaign-head"><div><small>مساحة الحملة</small><h3>${title}</h3></div><span class="pill">خطة أولية</span></div>
    <div class="campaign-columns"><article><b>الفكرة</b><div class="campaign-block violet">رسالة واضحة</div><div class="campaign-block pale">نبرة العلامة</div></article><article><b>المحتوى</b><div class="campaign-block teal">منشور تعريفي</div><div class="campaign-block peach">دعوة للتفاعل</div></article><article><b>النشر</b><div class="calendar"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><small>تقويم محتوى</small></article></div>
  </div>`;
  if (category === 'video') return `<div class="video-preview">
    <div class="video-screen"><div class="video-sun"></div><div class="video-hills"></div><button class="play-toggle" type="button" aria-label="تشغيل المعاينة">▶</button><span class="video-caption">إطار تجريبي للمشهد</span></div>
    <div class="timeline"><div class="timeline-tools"><b>مسار العمل</b><span>00:00 ━━━━━━━━━ 00:30</span></div><div class="track"><small>الصورة</small><i></i><i></i><i></i></div><div class="track audio"><small>الصوت</small><i></i></div></div>
  </div>`;
  return `<div class="service-preview">
    <div class="service-top"><span class="service-mark">J</span><span>مساحة المشروع</span><span class="service-menu">•••</span></div>
    <div class="service-welcome"><small>التصور المقترح</small><h3>${title}</h3><p>واجهة أولية توضّح الفكرة قبل بدء التنفيذ.</p><button class="preview-action" type="button" data-scroll="details">استكشف الفكرة <span>←</span></button></div>
    <div class="service-cards"><article><span>01</span><b>الفكرة</b><i></i></article><article><span>02</span><b>التفاصيل</b><i></i></article><article><span>03</span><b>الخطوة التالية</b><i></i></article></div>
  </div>`;
}

